import{_ as o,o as t,c as s,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse(`{"title":"Extending Ceph's Reach - Tushar Gohad, Zhong Xin","description":"","frontmatter":{"title":"Extending Ceph's Reach - Tushar Gohad, Zhong Xin","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-23T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Extending_Ceph_s_Reach_-_Tushar_Gohad_Zhong_Xin.md","filePath":"posts/2018/Extending_Ceph_s_Reach_-_Tushar_Gohad_Zhong_Xin.md","lastUpdated":1780459816000}`),p={name:"posts/2018/Extending_Ceph_s_Reach_-_Tushar_Gohad_Zhong_Xin.md"};function r(a,e,h,l,g,i){return t(),s("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 扩展Ceph分布式存储的覆盖范围与应用</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 李浩，Tushar Goel（英特尔首席工程师），以及来自英特尔、红帽、思杰等公司的代表</p><p><strong>会议内容</strong>：</p><p><strong>1. 会议开场</strong></p><p>李浩对与会嘉宾表示感谢并介绍了本次会议的演讲者Tushar Goel，他是英特尔的首席工程师，专注于软件定义存储领域已有五年以上。</p><p><strong>2. Ceph存储的未来</strong></p><p>Tushar Goel指出，随着数据量的激增，存储需求也在不断增长。英特尔致力于扩展Ceph存储的覆盖范围，引入新的工作负载。他强调了开源社区的重要性，并介绍了英特尔在Ceph社区中的贡献。</p><p><strong>3. 数据增长趋势</strong></p><p>Tushar Goel分析了数据增长的来源，包括互联网用户、智能工厂、智能汽车等，强调中国在这一增长故事中的重要性。</p><p><strong>4. Ceph用户案例</strong></p><p>Tushar Goel展示了Ceph的一些用户案例，如Wall Street Journal、Facebook、Salesforce等，这些公司都在使用Ceph存储数据。</p><p><strong>5. Ceph技术发展</strong></p><p>Tushar Goel介绍了英特尔在Ceph技术方面的贡献，包括性能优化、管理性提升等。他重点介绍了以下几个方面：</p><ul><li><strong>非易失性内存（NVM）</strong>： 英特尔正在与社区合作，将NVM编程模型应用于异步OSD，以降低延迟，提高性能。</li><li><strong>数据缓存</strong>： 英特尔正在优化数据缓存策略，将数据更接近应用程序，减少网络延迟。</li><li><strong>压缩和加密</strong>： 英特尔正在支持压缩和加密功能，以保护数据安全。</li></ul><p><strong>6. 存储趋势</strong></p><p>Tushar Goel探讨了存储领域的三个趋势：</p><ul><li><strong>非易失性内存</strong>： 随着NVM的普及，存储系统软件的延迟将越来越低，需要重新思考软件堆栈的设计。</li><li><strong>解耦</strong>： 通过解耦计算、存储和网络资源，可以提高数据中心的效率和可扩展性。</li><li><strong>管理性</strong>： 随着工作负载的增长，需要提高Ceph的管理性，包括监控、调优和故障排除。</li></ul><p><strong>7. Ceph在公益领域的应用</strong></p><p>Tushar Goel分享了Ceph在公益领域的应用案例，如National Center for Missing and Exploited Children。该组织使用Ceph存储大量数据，并取得了显著成效。</p><p><strong>8. 总结与展望</strong></p><p>Tushar Goel总结了本次会议的主要内容，并展望了Ceph存储的未来。他强调，英特尔将继续与社区合作，推动Ceph存储的发展，并为更多用户带来价值。</p><p><strong>后续行动计划</strong>：</p><ul><li>继续优化Ceph性能和管理性。</li><li>推动Ceph在更多领域的应用。</li><li>加强与社区的合作，共同推动Ceph存储的发展。</li></ul>',25)])])}const u=o(p,[["render",r]]);export{d as __pageData,u as default};
